const body = $json.body || {};
const pageId = String(body.pageId || '').replace(/-/g, '');
if (!/^[0-9a-f]{32}$/i.test(pageId)) {
  throw new Error('pageId manquant ou invalide');
}
return [{ json: { pageId } }];

const page = $json;
const pageId = $('Valider Entree').first().json.pageId;

function texte(prop) {
  if (!prop) return '';
  const arr = prop.rich_text || prop.title || [];
  return arr.map(t => t.plain_text || '').join(' ').trim();
}

const p = page.properties || {};
const sections = [
  ['Titre', texte(p['Nom'])],
  ['Resume', texte(p['Resume'])],
  ['Themes dominants', texte(p['Themes Dominants'])],
  ['Points forts concurrents', texte(p['Points Forts Concurrents'])],
  ['Concurrents', texte(p['Concurrents'])],
  ['Angles non exploites', texte(p['Angles Non Exploites'])],
  ['Formats performants', texte(p['Formats Performants'])],
  ['Recommandations', texte(p['Recommandations'])],
].filter(([, v]) => v);

if (!sections.length) {
  throw new Error('Ligne de veille vide : rien a analyser');
}

const contenu = sections.map(([k, v]) => k + ' : ' + v).join('\n');

const prompt = `Tu aides Anna Ollivier, psychologue clinicienne specialisee en developpement emotionnel de l'enfant, a creer du contenu pour ses reseaux sociaux.

Voici une veille sur des publications de comptes concurrents :

${contenu}

Ta mission : extraire l'IDEE DE FOND la plus forte publiee par la concurrence et la reformuler en francais sous forme d'un PROMPT de creation de contenu pret a l'emploi pour Anna.

Regles strictes :
- Reprends uniquement l'idee psychologique ou educative du post (le message transmis au parent), JAMAIS le contexte de mise en scene (lieu, personnages, anecdote type "une femme au supermarche").
- Ecris tout en francais naturel.
- Le prompt doit etre directement utilisable : il decrit l'idee a transmettre, l'angle, et le ton bienveillant d'Anna.
- Termine par une ligne "Idee source :" qui resume en une phrase l'idee du post concurrent.
- Pas de hashtags, pas d'emojis, maximum 250 mots.

Reponds UNIQUEMENT avec le prompt, sans preambule ni commentaire.`;

return [{ json: { pageId, prompt } }];

const pageId = $('Valider Entree').first().json.pageId;
const rep = $json;
const contenu = (((rep.message || {}).content) || '').trim();
if (!contenu) {
  throw new Error('Reponse LLM vide : ' + JSON.stringify(rep).slice(0, 300));
}
return [{ json: { pageId, promptGenere: contenu.slice(0, 1900) } }];
